T("09-cli-bibliography-export", L("Bibliography export and draft conversion", "Exportul bibliografiei și conversia draftului", "Export de la bibliographie et conversion du brouillon", "Esportare la bibliografia e convertire la bozza", "Exportar la bibliografía y convertir el borrador", "Exportar a bibliografia e converter o rascunho", "Bibliographie exportieren und Entwurf konvertieren", "Bibliográfia exportálása és a vázlat átalakítása"), "term", [
    Scene(L("`bib` exports your .bib files as RIS, CSL JSON or BibTeX, ready for Zotero, Mendeley, pandoc or Word.", "`bib` exportă fișierele .bib ca RIS, CSL JSON sau BibTeX, gata pentru Zotero, Mendeley, pandoc sau Word.", "`bib` exporte vos fichiers .bib en RIS, CSL JSON ou BibTeX, prêts pour Zotero, Mendeley, pandoc ou Word.", "`bib` esporta i tuoi file .bib come RIS, CSL JSON o BibTeX, pronti per Zotero, Mendeley, pandoc o Word.", "`bib` exporta tus archivos .bib como RIS, CSL JSON o BibTeX, listos para Zotero, Mendeley, pandoc o Word.", "`bib` exporta seus arquivos .bib como RIS, CSL JSON ou BibTeX, prontos para Zotero, Mendeley, pandoc ou Word.", "`bib` exportiert deine .bib-Dateien als RIS, CSL JSON oder BibTeX – bereit für Zotero, Mendeley, pandoc oder Word.", "A `bib` RIS, CSL JSON vagy BibTeX formátumban exportálja a .bib fájlokat Zotero, Mendeley, pandoc vagy Word számára."),
          lambda c: c.cmd("tezaur bib --bib lib/refs.bib --to ris", n=16)),
    Scene(L("The same entries as CSL JSON, the format pandoc and many reference managers read.", "Aceleași intrări ca CSL JSON, formatul citit de pandoc și de mulți manageri de referințe.", "Les mêmes entrées en CSL JSON, le format lu par pandoc et de nombreux gestionnaires de références.", "Le stesse voci come CSL JSON, il formato letto da pandoc e da molti gestori di riferimenti.", "Las mismas entradas como CSL JSON, el formato que leen pandoc y muchos gestores de referencias.", "As mesmas entradas como CSL JSON, o formato lido por pandoc e por muitos gestores de referências.", "Dieselben Einträge als CSL JSON, das Format von pandoc und vielen Literaturverwaltungen.", "Ugyanezek CSL JSON-ként, amit a pandoc és sok referenciakezelő olvas."),
          lambda c: c.cmd("tezaur bib --bib lib/refs.bib --to csl-json | head -18", shown="tezaur bib --bib lib/refs.bib --to csl-json | head -18")),
    Scene(L("`export` converts a Markdown draft: [@key] citations become \\cite{key} in LaTeX, or a reference list in Word and HTML.", "`export` convertește un draft Markdown: citările [@cheie] devin \\cite{cheie} în LaTeX sau listă de referințe în Word și HTML.", "`export` convertit un brouillon Markdown : les citations [@clé] deviennent \\cite{clé} en LaTeX, ou une liste de références en Word et HTML.", "`export` converte una bozza Markdown: le citazioni [@chiave] diventano \\cite{chiave} in LaTeX, o un elenco di riferimenti in Word e HTML.", "`export` convierte un borrador Markdown: las citas [@clave] pasan a \\cite{clave} en LaTeX, o a lista de referencias en Word y HTML.", "`export` converte um rascunho Markdown: as citações [@chave] viram \\cite{chave} em LaTeX, ou lista de referências em Word e HTML.", "`export` wandelt einen Markdown-Entwurf um: [@Schlüssel] wird in LaTeX zu \\cite{Schlüssel}, in Word/HTML zur Literaturliste.", "Az `export` Markdown vázlatot alakít át: a [@kulcs] hivatkozásból LaTeX-ben \\cite{kulcs}, Wordben és HTML-ben irodalomjegyzék lesz."),
          lambda c: c.cmd("tezaur export work/draft.md --to tex -o out.tex --bib-name refs && grep -n cite out.tex", shown="tezaur export work/draft.md --to tex -o out.tex --bib-name refs && grep -n cite out.tex")),
])

