MCP_CALLS = ("printf '%s\\n' "
  "'{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"initialize\",\"params\":{\"protocolVersion\":\"2024-11-05\",\"capabilities\":{},\"clientInfo\":{\"name\":\"demo\",\"version\":\"1\"}}}' "
  "'{\"jsonrpc\":\"2.0\",\"method\":\"notifications/initialized\"}' ")
T("10-mcp-assistant", L("Use your library from an AI assistant (MCP)", "Folosește biblioteca dintr-un asistent AI (MCP)", "Utiliser votre bibliothèque depuis un assistant IA (MCP)", "Usare la tua biblioteca da un assistente IA (MCP)", "Usar tu biblioteca desde un asistente de IA (MCP)", "Usar a sua biblioteca a partir de um assistente de IA (MCP)", "Deine Bibliothek aus einem KI-Assistenten nutzen (MCP)", "A könyvtárad használata MI-asszisztensből (MCP)"), "term", [
    Scene(L("`tezaur mcp` is a Model Context Protocol server over stdio: Claude Desktop, Claude Code or Cursor can read your library, read-only.", "`tezaur mcp` e un server Model Context Protocol pe stdio: Claude Desktop, Claude Code sau Cursor îți pot citi biblioteca, doar în citire.", "`tezaur mcp` est un serveur Model Context Protocol sur stdio : Claude Desktop, Claude Code ou Cursor lisent votre bibliothèque, en lecture seule.", "`tezaur mcp` è un server Model Context Protocol su stdio: Claude Desktop, Claude Code o Cursor leggono la tua biblioteca, in sola lettura.", "`tezaur mcp` es un servidor Model Context Protocol por stdio: Claude Desktop, Claude Code o Cursor leen tu biblioteca, solo lectura.", "`tezaur mcp` é um servidor Model Context Protocol via stdio: Claude Desktop, Claude Code ou Cursor leem a sua biblioteca, só leitura.", "`tezaur mcp` ist ein Model-Context-Protocol-Server über stdio: Claude Desktop, Claude Code oder Cursor lesen deine Bibliothek, nur lesend.", "A `tezaur mcp` egy Model Context Protocol szerver stdio-n: a Claude Desktop, Claude Code vagy Cursor csak olvasásra elérheti a könyvtárad."),
          lambda c: c.cmd("tezaur mcp --help | head -3", n=4)),
    Scene(L("A client talks JSON-RPC. Here we play the client ourselves: initialize, then ask which tools exist.", "Un client vorbește JSON-RPC. Aici jucăm noi clientul: inițializăm, apoi întrebăm ce unelte există.", "Un client parle JSON-RPC. Ici nous jouons le client : initialisation, puis la liste des outils.", "Un client parla JSON-RPC. Qui facciamo noi il client: inizializzazione, poi chiediamo quali strumenti esistono.", "Un cliente habla JSON-RPC. Aquí hacemos de cliente: inicializamos y preguntamos qué herramientas hay.", "Um cliente fala JSON-RPC. Aqui fazemos de cliente: inicializamos e perguntamos que ferramentas existem.", "Ein Client spricht JSON-RPC. Hier spielen wir den Client: initialisieren, dann nach den Werkzeugen fragen.", "Egy kliens JSON-RPC-n beszél. Itt mi játsszuk a klienst: inicializálás, majd az eszközök lekérdezése."),
          lambda c: c.cmd(MCP_CALLS + "'{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"tools/list\"}' | tezaur mcp 2>/dev/null | python3 -c \"import sys,json;[print(t['name'],'(',', '.join(t['inputSchema']['properties']),')') for t in json.loads(sys.stdin.readlines()[1])['result']['tools']]\"",
                          shown="… | tezaur mcp   # tools/list", n=10)),
    Scene(L("Call `tezaur_search`: the passages come back with citation labels the assistant must use as its only evidence.", "Apelăm `tezaur_search`: pasajele revin cu etichete de citare pe care asistentul trebuie să le folosească drept unică dovadă.", "Appel de `tezaur_search` : les passages reviennent avec des étiquettes de citation, seule preuve admise pour l'assistant.", "Chiamiamo `tezaur_search`: i passaggi tornano con etichette di citazione, unica prova che l'assistente deve usare.", "Llamamos a `tezaur_search`: los pasajes vuelven con etiquetas de cita, la única evidencia que debe usar el asistente.", "Chamamos `tezaur_search`: as passagens voltam com rótulos de citação, a única evidência que o assistente deve usar.", "Aufruf von `tezaur_search`: Die Stellen kommen mit Zitierlabels zurück – die einzige Evidenz für den Assistenten.", "Meghívjuk a `tezaur_search`-öt: a szövegrészek idézési címkékkel jönnek, ezek az asszisztens egyetlen bizonyítéka."),
          lambda c: c.cmd(MCP_CALLS + "'{\"jsonrpc\":\"2.0\",\"id\":3,\"method\":\"tools/call\",\"params\":{\"name\":\"tezaur_search\",\"arguments\":{\"query\":\"aptitude test\",\"k\":1}}}' | tezaur mcp 2>/dev/null | python3 -c \"import sys,json;print(json.loads(sys.stdin.readlines()[1])['result']['content'][0]['text'][:520])\"",
                          shown="… | tezaur mcp   # tools/call tezaur_search", n=10)),
    Scene(L("Add it to your client's config as command `tezaur`, args `mcp` and `--index` — the repository has ready-made snippets.", "Adaug-o în configurarea clientului ca comandă `tezaur`, argumente `mcp` și `--index` — depozitul are fragmente gata făcute.", "Ajoutez-le à la config du client : commande `tezaur`, arguments `mcp` et `--index` — le dépôt fournit des extraits prêts.", "Aggiungilo alla config del client: comando `tezaur`, argomenti `mcp` e `--index` — il repository ha snippet pronti.", "Añádelo a la config del cliente: comando `tezaur`, argumentos `mcp` y `--index` — el repositorio trae fragmentos listos.", "Adicione à config do cliente: comando `tezaur`, argumentos `mcp` e `--index` — o repositório tem trechos prontos.", "Trage es in die Client-Konfiguration ein: Befehl `tezaur`, Argumente `mcp` und `--index` – das Repository hat fertige Snippets.", "Add a kliens konfigurációjához: parancs `tezaur`, argumentumok `mcp` és `--index` — a tárolóban kész minták vannak."),
          lambda c: c.cmd("echo '{\"mcpServers\":{\"tezaur\":{\"command\":\"tezaur\",\"args\":[\"mcp\",\"--index\",\"/home/you/thesis/tezaur.idx\"]}}}'", n=4)),
])

# ---------------------------------------------------------------- 11
T("11-server-api", L("Run the local web server and its JSON API", "Rulează serverul web local și API-ul lui JSON", "Lancer le serveur web local et son API JSON", "Avviare il server web locale e la sua API JSON", "Ejecutar el servidor web local y su API JSON", "Executar o servidor web local e a sua API JSON", "Den lokalen Webserver und seine JSON-API starten", "A helyi webszerver és JSON API indítása"), "term", [
    Scene(L("`tezaur serve` starts the web app, a JSON API over your index, named workspaces and a same-origin proxy to the model server.", "`tezaur serve` pornește aplicația web, un API JSON peste index, spații de lucru numite și un proxy same-origin către serverul de model.", "`tezaur serve` lance l'appli web, une API JSON sur l'index, des espaces de travail nommés et un proxy same-origin vers le modèle.", "`tezaur serve` avvia l'app web, un'API JSON sull'indice, spazi di lavoro con nome e un proxy same-origin verso il modello.", "`tezaur serve` inicia la app web, una API JSON sobre el índice, espacios de trabajo con nombre y un proxy same-origin al modelo.", "`tezaur serve` inicia a app web, uma API JSON sobre o índice, espaços de trabalho nomeados e um proxy same-origin para o modelo.", "`tezaur serve` startet die Web-App, eine JSON-API über den Index, benannte Arbeitsbereiche und einen Same-Origin-Proxy zum Modell.", "A `tezaur serve` elindítja a webalkalmazást, a JSON API-t az index fölött, névvel ellátott munkaterületeket és egy same-origin proxyt a modellhez."),
          lambda c: c.cmd("(tezaur serve --port 8853 >/dev/null 2>&1 &) ; sleep 1.5; echo 'listening on http://127.0.0.1:8853'", shown="tezaur serve --port 8853 &")),
    Scene(L("By default it binds to 127.0.0.1 only. `/api/health` tells you it is alive.", "Implicit ascultă doar pe 127.0.0.1. `/api/health` îți spune că e în viață.", "Par défaut il n'écoute que sur 127.0.0.1. `/api/health` indique qu'il est en vie.", "Per impostazione predefinita ascolta solo su 127.0.0.1. `/api/health` dice che è vivo.", "Por defecto solo escucha en 127.0.0.1. `/api/health` indica que está vivo.", "Por padrão só escuta em 127.0.0.1. `/api/health` diz que está vivo.", "Standardmäßig lauscht er nur auf 127.0.0.1. `/api/health` zeigt, dass er lebt.", "Alapból csak a 127.0.0.1-en figyel. Az `/api/health` jelzi, hogy él."),
          lambda c: c.cmd("curl -s 127.0.0.1:8853/api/health", n=4)),
    Scene(L("The same search as the CLI, over HTTP: build your own tools on top.", "Aceeași căutare ca în CLI, prin HTTP: poți construi propriile unelte peste ea.", "La même recherche que la CLI, en HTTP : construisez vos propres outils par-dessus.", "La stessa ricerca della CLI, via HTTP: costruisci i tuoi strumenti sopra.", "La misma búsqueda que la CLI, por HTTP: construye tus propias herramientas encima.", "A mesma pesquisa da CLI, via HTTP: construa as suas ferramentas por cima.", "Dieselbe Suche wie in der CLI, per HTTP: Baue eigene Werkzeuge darauf.", "Ugyanaz a keresés, mint a CLI-ben, HTTP-n: építhetsz rá saját eszközöket."),
          lambda c: c.cmd("curl -s '127.0.0.1:8853/api/search?q=aptitude+test&k=1' | python3 -c \"import sys,json;h=json.load(sys.stdin)['hits'][0];print(h['label'],'| covers',h['cov'],'|',h['text'][:150])\"", shown="curl '127.0.0.1:8853/api/search?q=aptitude+test&k=1'")),
    Scene(L("Other endpoints: /api/sources, /api/audit, /api/refs, /api/coverage, /api/bib, /api/ingest and /api/mesh/*.", "Alte endpoint-uri: /api/sources, /api/audit, /api/refs, /api/coverage, /api/bib, /api/ingest și /api/mesh/*.", "Autres points d'accès : /api/sources, /api/audit, /api/refs, /api/coverage, /api/bib, /api/ingest et /api/mesh/*.", "Altri endpoint: /api/sources, /api/audit, /api/refs, /api/coverage, /api/bib, /api/ingest e /api/mesh/*.", "Otros endpoints: /api/sources, /api/audit, /api/refs, /api/coverage, /api/bib, /api/ingest y /api/mesh/*.", "Outros endpoints: /api/sources, /api/audit, /api/refs, /api/coverage, /api/bib, /api/ingest e /api/mesh/*.", "Weitere Endpunkte: /api/sources, /api/audit, /api/refs, /api/coverage, /api/bib, /api/ingest und /api/mesh/*.", "További végpontok: /api/sources, /api/audit, /api/refs, /api/coverage, /api/bib, /api/ingest és /api/mesh/*."),
          lambda c: c.cmd("curl -s 127.0.0.1:8853/api/sources | python3 -c \"import sys,json;d=json.load(sys.stdin);print([x['title'] for x in d['docs']])\"; pkill -f 'serve --port 8853'; echo stopped", shown="curl 127.0.0.1:8853/api/sources", n=5)),
])

# ---------------------------------------------------------------- 12
T("12-mesh-p2p", L("Mesh: share libraries peer to peer", "Mesh: partajează biblioteci între colegi (P2P)", "Mesh : partager des bibliothèques de pair à pair", "Mesh: condividere biblioteche tra pari (P2P)", "Mesh: compartir bibliotecas de igual a igual", "Mesh: compartilhar bibliotecas ponto a ponto", "Mesh: Bibliotheken von Peer zu Peer teilen", "Mesh: könyvtárak megosztása peer-to-peer"), "term", [
    Scene(L("Mesh lets two researchers exchange passages and documents directly, with no central server. Here two nodes run on one machine.", "Mesh permite a doi cercetători să schimbe pasaje și documente direct, fără server central. Aici două noduri rulează pe același calculator.", "Mesh permet à deux chercheurs d'échanger passages et documents directement, sans serveur central. Ici deux nœuds sur une machine.", "Mesh permette a due ricercatori di scambiare passaggi e documenti direttamente, senza server centrale. Qui due nodi su una macchina.", "Mesh permite a dos investigadores intercambiar pasajes y documentos directamente, sin servidor central. Aquí dos nodos en una máquina.", "Mesh permite a dois investigadores trocar passagens e documentos diretamente, sem servidor central. Aqui dois nós numa máquina.", "Mesh lässt zwei Forschende Stellen und Dokumente direkt austauschen, ohne zentralen Server. Hier laufen zwei Knoten auf einem Rechner.", "A Mesh két kutatónak lehetővé teszi, hogy központi szerver nélkül közvetlenül cseréljenek szövegrészeket és dokumentumokat. Itt két csomópont fut egy gépen."),
          lambda c: c.cmd("mkdir -p ana bob && export A=ana/t.idx B=bob/t.idx && TEZAUR_INDEX=$A tezaur ingest lib >/dev/null && TEZAUR_INDEX=$A tezaur mesh name ana && TEZAUR_INDEX=$A tezaur mesh share lisbon directive", shown="tezaur ingest lib; tezaur mesh name ana; tezaur mesh share lisbon directive", n=8)),
    Scene(L("Ana shares only what she chose: documents matching 'lisbon' or 'directive'. The rest stays private.", "Ana partajează doar ce a ales: documentele care conțin „lisbon” sau „directive”. Restul rămâne privat.", "Ana ne partage que ce qu'elle a choisi : les documents contenant « lisbon » ou « directive ». Le reste reste privé.", "Ana condivide solo ciò che ha scelto: i documenti con «lisbon» o «directive». Il resto resta privato.", "Ana comparte solo lo que eligió: documentos con «lisbon» o «directive». Lo demás sigue privado.", "Ana partilha só o que escolheu: documentos com «lisbon» ou «directive». O resto fica privado.", "Ana teilt nur, was sie gewählt hat: Dokumente mit „lisbon“ oder „directive“. Der Rest bleibt privat.", "Ana csak azt osztja meg, amit választott: a „lisbon” vagy „directive” szavú dokumentumokat. A többi privát marad."),
          lambda c: c.cmd("(TEZAUR_INDEX=$PWD/ana/t.idx tezaur serve --port 8861 >/dev/null 2>&1 &); sleep 1.5; TEZAUR_INDEX=ana/t.idx tezaur mesh status", shown="tezaur serve --port 8861 &   # Ana's node", n=12)),
    Scene(L("Bob adds Ana as a peer and searches her library. Nothing is copied: only matching snippets come back.", "Bob o adaugă pe Ana ca peer și îi caută biblioteca. Nu se copiază nimic: revin doar fragmentele potrivite.", "Bob ajoute Ana comme pair et cherche dans sa bibliothèque. Rien n'est copié : seuls les extraits correspondants reviennent.", "Bob aggiunge Ana come peer e cerca nella sua biblioteca. Nulla viene copiato: tornano solo gli snippet corrispondenti.", "Bob añade a Ana como peer y busca en su biblioteca. No se copia nada: solo vuelven los fragmentos coincidentes.", "Bob adiciona a Ana como peer e pesquisa a biblioteca dela. Nada é copiado: voltam só os trechos correspondentes.", "Bob fügt Ana als Peer hinzu und durchsucht ihre Bibliothek. Nichts wird kopiert: nur passende Ausschnitte kommen zurück.", "Bob hozzáadja Anát peerként, és keres a könyvtárában. Semmi sem másolódik: csak a találati részletek érkeznek."),
          lambda c: c.cmd("export TEZAUR_INDEX=$PWD/bob/t.idx; tezaur mesh add ana http://127.0.0.1:8861 && tezaur mesh search 'aptitude test' -k 1", shown="tezaur mesh add ana http://127.0.0.1:8861; tezaur mesh search 'aptitude test'", n=10)),
    Scene(L("`mesh pull` copies Ana's shared documents into Bob's index; for offline exchange use `mesh export` and `mesh import` with a .tzb bundle on a USB stick.", "`mesh pull` copiază documentele partajate ale Anei în indexul lui Bob; pentru schimb offline folosește `mesh export` și `mesh import` cu un pachet .tzb pe stick USB.", "`mesh pull` copie les documents partagés d'Ana dans l'index de Bob ; hors ligne, `mesh export` et `mesh import` avec un paquet .tzb sur clé USB.", "`mesh pull` copia i documenti condivisi di Ana nell'indice di Bob; offline usa `mesh export` e `mesh import` con un pacchetto .tzb su chiavetta USB.", "`mesh pull` copia los documentos compartidos de Ana al índice de Bob; sin conexión usa `mesh export` y `mesh import` con un paquete .tzb en USB.", "`mesh pull` copia os documentos partilhados da Ana para o índice do Bob; offline use `mesh export` e `mesh import` com um pacote .tzb num pen USB.", "`mesh pull` kopiert Anas geteilte Dokumente in Bobs Index; offline: `mesh export` und `mesh import` mit einem .tzb-Paket per USB-Stick.", "A `mesh pull` átmásolja Ana megosztott dokumentumait Bob indexébe; offline a `mesh export` és `mesh import` használható .tzb csomaggal USB-n."),
          lambda c: c.cmd("export TEZAUR_INDEX=$PWD/bob/t.idx; tezaur mesh pull ana; tezaur sources; pkill -f 'serve --port 8861'; true", shown="tezaur mesh pull ana; tezaur sources", n=12)),
])

# ---------------------------------------------------------------- 13
BASE = "BASE=https://chiuta.github.io/TEZAUR"
T("13-install", L("Install TEZAUR", "Instalează TEZAUR", "Installer TEZAUR", "Installare TEZAUR", "Instalar TEZAUR", "Instalar o TEZAUR", "TEZAUR installieren", "A TEZAUR telepítése"), "term", [
    Scene(L("Commands in this tutorial are shown from the README and are not executed in the recording; CI runs them on every push.", "Comenzile din acest tutorial sunt luate din README și nu sunt rulate în înregistrare; CI le rulează la fiecare push.", "Les commandes de ce tutoriel viennent du README et ne sont pas exécutées dans l'enregistrement ; la CI les lance à chaque push.", "I comandi di questo tutorial sono tratti dal README e non vengono eseguiti nella registrazione; la CI li esegue a ogni push.", "Los comandos de este tutorial provienen del README y no se ejecutan en la grabación; la CI los ejecuta en cada push.", "Os comandos deste tutorial vêm do README e não são executados na gravação; a CI executa-os a cada push.", "Die Befehle in diesem Tutorial stammen aus dem README und werden in der Aufnahme nicht ausgeführt; die CI führt sie bei jedem Push aus.", "A bemutató parancsai a README-ből valók, a felvételen nem futnak le; a CI minden push-nál lefuttatja őket."),
          lambda c: c.cmd("true", shown="BASE=https://chiuta.github.io/TEZAUR", out="")),
    Scene(L("Debian and Ubuntu: add the repository, then `apt install tezaur`. It is unsigned, hence trusted=yes.", "Debian și Ubuntu: adaugă depozitul, apoi `apt install tezaur`. Nu e semnat, de aceea trusted=yes.", "Debian et Ubuntu : ajoutez le dépôt puis `apt install tezaur`. Il n'est pas signé, d'où trusted=yes.", "Debian e Ubuntu: aggiungi il repository e poi `apt install tezaur`. Non è firmato, da cui trusted=yes.", "Debian y Ubuntu: añade el repositorio y luego `apt install tezaur`. No está firmado, de ahí trusted=yes.", "Debian e Ubuntu: adicione o repositório e depois `apt install tezaur`. Não é assinado, daí trusted=yes.", "Debian und Ubuntu: Repository hinzufügen, dann `apt install tezaur`. Es ist nicht signiert, daher trusted=yes.", "Debian és Ubuntu: add hozzá a tárolót, majd `apt install tezaur`. Nincs aláírva, ezért trusted=yes."),
          lambda c: c.cmd("true", shown='echo "deb [trusted=yes] $BASE/apt ./" | sudo tee /etc/apt/sources.list.d/tezaur.list && sudo apt update && sudo apt install tezaur', out="")),
    Scene(L("Fedora and RHEL: download the .repo file, then `dnf install tezaur` (gpgcheck is off for the same reason).", "Fedora și RHEL: descarcă fișierul .repo, apoi `dnf install tezaur` (gpgcheck e oprit din același motiv).", "Fedora et RHEL : téléchargez le fichier .repo puis `dnf install tezaur` (gpgcheck est désactivé pour la même raison).", "Fedora e RHEL: scarica il file .repo e poi `dnf install tezaur` (gpgcheck è disattivato per lo stesso motivo).", "Fedora y RHEL: descarga el archivo .repo y luego `dnf install tezaur` (gpgcheck está desactivado por lo mismo).", "Fedora e RHEL: baixe o arquivo .repo e depois `dnf install tezaur` (gpgcheck está desligado pelo mesmo motivo).", "Fedora und RHEL: .repo-Datei laden, dann `dnf install tezaur` (gpgcheck ist aus demselben Grund aus).", "Fedora és RHEL: töltsd le a .repo fájlt, majd `dnf install tezaur` (a gpgcheck ugyanezért ki van kapcsolva)."),
          lambda c: c.cmd("true", shown="sudo curl -o /etc/yum.repos.d/tezaur.repo $BASE/rpm/tezaur.repo && sudo dnf install tezaur", out="")),
    Scene(L("Flatpak: add the remote and install tf.trom.Tezaur. On Android, add the F-Droid repository URL in the F-Droid app.", "Flatpak: adaugă remote-ul și instalează tf.trom.Tezaur. Pe Android, adaugă URL-ul depozitului F-Droid în aplicația F-Droid.", "Flatpak : ajoutez le dépôt distant et installez tf.trom.Tezaur. Sur Android, ajoutez l'URL du dépôt F-Droid dans l'appli F-Droid.", "Flatpak: aggiungi il remote e installa tf.trom.Tezaur. Su Android aggiungi l'URL del repository F-Droid nell'app F-Droid.", "Flatpak: añade el remoto e instala tf.trom.Tezaur. En Android, añade la URL del repositorio F-Droid en la app F-Droid.", "Flatpak: adicione o remoto e instale tf.trom.Tezaur. No Android, adicione o URL do repositório F-Droid na app F-Droid.", "Flatpak: Remote hinzufügen und tf.trom.Tezaur installieren. Unter Android die F-Droid-Repository-URL in der F-Droid-App eintragen.", "Flatpak: add hozzá a távoli tárolót és telepítsd a tf.trom.Tezaur-t. Androidon az F-Droid alkalmazásban add meg a tároló URL-jét."),
          lambda c: c.cmd("true", shown="flatpak remote-add --user tezaur $BASE/flatpak/tezaur.flatpakrepo && flatpak install tezaur tf.trom.Tezaur", out="")),
    Scene(L("Or build from source with cargo. This one is really executed here: the version of the binary used in all these tutorials.", "Sau compilează din sursă cu cargo. Aceasta chiar e rulată aici: versiunea binarului folosit în toate tutorialele.", "Ou compilez depuis les sources avec cargo. Celle-ci est réellement exécutée : la version du binaire utilisé dans tous ces tutoriels.", "Oppure compila dai sorgenti con cargo. Questo è davvero eseguito qui: la versione del binario usato in tutti i tutorial.", "O compila desde el código con cargo. Esto sí se ejecuta aquí: la versión del binario usado en todos los tutoriales.", "Ou compile a partir do código com cargo. Isto é mesmo executado aqui: a versão do binário usado em todos os tutoriais.", "Oder mit cargo aus dem Quellcode bauen. Das hier läuft wirklich: die Version des Binärprogramms aus allen Tutorials.", "Vagy fordítsd forrásból cargóval. Ez tényleg lefut itt: a bemutatókban használt program verziója."),
          lambda c: c.cmd("tezaur --version", shown="cargo build --release && target/release/tezaur --version", n=3)),
])
